"""Offline HTML/SVG presentation for the TCP interval-history search."""
from __future__ import annotations

import html
import json
from pathlib import Path


def sequence_svg(probe: dict, template: dict) -> str:
    """A downloadable, self-contained packet-exchange figure."""
    esc = lambda x: html.escape(str(x), quote=True)
    segs = probe.get("segments", [])
    height = 370 + 64 * len(segs)
    parts = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 {height}" width="1000" height="{height}" role="img" aria-label="Packet exchange for {esc(probe.get("id", ""))}">',
             '<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8Z" fill="#738295"/></marker></defs>',
             f'<rect width="1000" height="{height}" fill="#fff"/>',
             '<g font-family="Helvetica,Arial,sans-serif" font-size="13" fill="#183147">',
             f'<text x="30" y="30" font-size="19" font-weight="700">{esc(probe.get("id", ""))} · {esc(probe.get("title", "Interval experiment"))}</text>',
             f'<text x="30" y="54" fill="#6c7885">OFFLINE PLAN · DPI outcome: UNMEASURED · {len(segs)} data packets · C={esc(probe.get("cost","?"))} · {esc(probe.get("max_holes","?"))} max geometric holes</text>']
    for x, label, color in [(110, "Client / attacker", "#117a8a"), (505, "DPI observation point", "#7450b2"), (895, "Linux server", "#42566d")]:
        parts += [f'<rect x="{x-91}" y="76" width="182" height="36" rx="9" fill="{color}"/>', f'<text x="{x}" y="99" text-anchor="middle" fill="white" font-weight="700">{label}</text>',f'<line x1="{x}" y1="116" x2="{x}" y2="{height-62}" stroke="#d5dee7" stroke-dasharray="5 5"/>']
    def arrow(y, start, end, text, color="#738295", dashed=False):
        parts.append(f'<text x="{(start+end)/2}" y="{y-9}" text-anchor="middle" fill="{color}">{esc(text)}</text>')
        parts.append(f'<line x1="{start}" y1="{y}" x2="{end}" y2="{y}" stroke="{color}" stroke-width="2" marker-end="url(#arrow)"'+(' stroke-dasharray="5 4"' if dashed else '')+'/>')
        direction=1 if end>start else -1
        parts.append(f'<polygon points="{end},{y} {end-8*direction},{y-4} {end-8*direction},{y+4}" fill="{color}"/>')
    arrow(151, 110, 895, "SYN · SEQ=ISN_C · ordinary TTL, valid checksum")
    arrow(192, 895, 110, "SYN|ACK · SEQ=ISN_S · ACK=ISN_C+1 · real ISN learned")
    arrow(233, 110, 895, "ACK · SEQ=ISN_C+1 · ACK=ISN_S+1 · genuine connection")
    for i, s in enumerate(segs):
        y=286+64*i
        color="#c87521" if s.get("variant")=="T" else "#0c8997"
        ttl=s.get("visibility", "ttl")=="ttl"
        label=f'{i+1}. [{s["start"]},{s["end"]}) · {s["end"]-s["start"]} bytes · SEQ=ISN_C+1+{s["start"]} · {s.get("variant", "T")}'
        arrow(y,110,505,label,color)
        if ttl:
            parts.append(f'<line x1="515" y1="{y}" x2="739" y2="{y}" stroke="{color}" stroke-width="1.7" stroke-dasharray="5 4" opacity=".55"/>')
            parts.append(f'<text x="754" y="{y+5}" fill="{color}" font-size="20">×</text><text x="625" y="{y+19}" text-anchor="middle" fill="#6c7885">expires before Linux</text>')
        else:
            parts.append(f'<line x1="515" y1="{y}" x2="878" y2="{y}" stroke="{color}" stroke-width="1.7" stroke-dasharray="5 4"/><text x="884" y="{y+6}" fill="#be493c" font-size="22">×</text><text x="696" y="{y+19}" text-anchor="middle" fill="#be493c">invalid TCP checksum → discard</text>')
        note=f'ACK=ISN_S+1 · {"server-expiring TTL" if ttl else "ordinary TTL"} · {s.get("checksum", "valid")} checksum'
        parts.append(f'<text x="120" y="{y+20}" font-size="11" fill="#6c7885">{esc(note)}</text>')
    cleanup=300+64*len(segs)
    arrow(cleanup,110,895,"Cleanup RST|ACK · real Linux frontier: SEQ=ISN_C+1", "#738295")
    parts += [f'<text x="500" y="{height-45}" text-anchor="middle" fill="#6c7885" font-size="11">T = {esc(probe.get("target_hostname",template.get("target","abcdefgh.example")))} · B = {esc(probe.get("benign_hostname",template.get("benign","abcdxygh.example")))}</text>', f'<text x="500" y="{height-24}" text-anchor="middle" fill="#6c7885">No Linux data ACK or TLS response is expected. Missing response is not a censorship signal.</text></g></svg>']
    return ''.join(parts)


def combined_svg(data: dict) -> str:
    probes=data.get('probes', [])
    groups={}
    for p in probes:
        groups.setdefault(p.get('family','ttl_valid'),[]).append(p)
    height=155+150*len(groups)
    out=[f'<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="{height}" viewBox="0 0 1100 {height}"><rect width="1100" height="{height}" fill="#f7f9fc"/><g font-family="Helvetica,Arial,sans-serif" fill="#183147"><text x="35" y="40" font-size="23" font-weight="700">TCP segmentation experiment families</text><text x="35" y="65" font-size="14" fill="#63758b">Coverage grouping; branches are experiment families, not a TCP reachability graph. Outcomes remain unmeasured.</text><rect x="35" y="100" width="210" height="48" rx="10" fill="#183147"/><text x="140" y="129" text-anchor="middle" fill="white">Genuine fresh connection</text>']
    for i,(family,ps) in enumerate(groups.items()):
        y=190+150*i
        out.extend([f'<path d="M140,148 V{y+23} H300" stroke="#b5c3d2" fill="none" stroke-width="2"/>',f'<rect x="300" y="{y}" width="290" height="54" rx="9" fill="#e8edf8"/><text x="320" y="{y+22}" font-weight="700">{html.escape(family)}</text><text x="320" y="{y+41}" font-size="13">{len(ps)} retained experiments</text>'])
        for j,key in enumerate(['leading_gap','after_inspection','cross_inspection_frontier','spans_multiple_regions']):
            selected=[p for p in ps if key in p.get('tags',[]) or p.get('source')==key]
            x=660
            yy=y-20+34*j
            out.append(f'<path d="M590,{y+27} H620 V{yy+10} H650" stroke="#b5c3d2" fill="none"/><text x="{x}" y="{yy+15}" font-size="13">{key.replace("_"," ")} · {len(selected)} explicitly tagged</text>')
    out.append('</g></svg>')
    return ''.join(out)


def render(data: dict, output: Path) -> None:
    output=Path(output)
    output.parent.mkdir(parents=True,exist_ok=True)
    # Escaping </script> prevents input fields from terminating the inert JSON block.
    serialized=json.dumps(data,separators=(',',':'),ensure_ascii=True).replace('<','\\u003c').replace('&','\\u0026')
    compact=next((b for b in data.get('bundles',[]) if b.get('id')=='segmented_sni'),None)
    highlight='Review the fingerprint bundles for modeled binary vectors and repeated-control costs.'
    if compact:
        highlight=(f'{" + ".join(compact["probe_ids"])} separate {compact["distinct_fingerprints"]} reference outcomes '
                   f'using {compact["connections"]} connections and {compact["data_packets"]} data packets. '
                   'No packet contains the complete target hostname. See Fingerprint bundles for vectors and repeated-control costs.')
    output.write_text(PAGE.replace('__RESULTS_JSON__',serialized).replace('__COMBINED_SVG__',combined_svg(data)).replace('__COMPACT_HIGHLIGHT__',html.escape(highlight)),encoding='utf-8')
    figures=output.parent/'probe_images'
    figures.mkdir(exist_ok=True)
    for probe in data.get('probes',[]):
        safe=''.join(c for c in str(probe['id']) if c.isalnum() or c in '_-')
        (figures/f'{safe}.svg').write_text(sequence_svg(probe,data.get('meta',{}).get('template',{})),encoding='utf-8')
    (output.parent/'combined.svg').write_text(combined_svg(data),encoding='utf-8')


